// Stage 1: validate. Same rule as route.py: a missing or malformed email rejects the lead,
// any other missing field is flagged and routing carries on.
// The Code node sandbox has no performance timer, so stamps are Date.now() (1 ms resolution).
const now = () => Date.now();
const start = $('Settings').first().json.t_start;

const REQUIRED = ['company', 'contact_name', 'email', 'region', 'source'];
const EMAIL_RE = /^[A-Za-z0-9._%+\-]+@[A-Za-z0-9\-]+(\.[A-Za-z0-9\-]+)*\.[A-Za-z]{2,}$/;

const body = $('Inbound form (Webhook)').first().json.body || {};
const lead = {};
for (const [k, v] of Object.entries(body)) lead[k] = typeof v === 'string' ? v.trim() : v;

const flags = [];
for (const f of REQUIRED) if (!lead[f]) flags.push(`missing_${f}`);
if (lead.email && !EMAIL_RE.test(lead.email)) flags.push('invalid_email');
const valid = !flags.includes('invalid_email') && !flags.includes('missing_email');

return [{
  json: {
    lead,
    valid,
    result: { lead_id: lead.lead_id || '', status: valid ? 'routed' : 'rejected', flags },
    stamps: { start, validate: now() },
  },
}];

// A rejected lead stops after validate: it has no usable email, so nobody can work it.
// The Code node sandbox has no performance timer, so stamps are Date.now() (1 ms resolution).
const now = () => Date.now();
const end = now();
const { result, stamps } = $input.first().json;
const round = (x) => Math.round(x * 100) / 100;
return [{
  json: {
    ...result,
    assigned_rep: '',
    stage_ms: { validate: round(stamps.validate - stamps.start) },
    total_ms: round(end - stamps.start),
  },
}];

// Stage 2: dedupe against the leads table.
// The table lives in this workflow's static data (saved by n8n after each production run), seeded
// with eight existing leads the first time it runs. Two checks, as in route.py:
//   * exact email (case-insensitive): the same person again -> duplicate_contact
//   * company name: a known account -> known_account. The normalised name matches exactly, or it
//     matches fuzzily (similarity >= 0.85) AND a second signal agrees: same contact surname or same
//     business email domain. Public mail domains never count as a signal.
// The Code node sandbox has no performance timer, so stamps are Date.now() (1 ms resolution).
const now = () => Date.now();
const item = $input.first().json;
const { lead, result, stamps } = item;

const SEED_LEADS = [
  { lead_id: 'L-0001', company: 'Larkwell Bakery LLC', contact_name: 'Nora Galloway', email: 'nora@larkwellbakery.example', owner: 'R03' },
  { lead_id: 'L-0002', company: 'Riverlight Clinic', contact_name: 'Sam Ortiz', email: 'sam@riverlightclinic.example', owner: 'R01' },
  { lead_id: 'L-0003', company: 'Brightpath Tutoring', contact_name: 'Ken Ito', email: 'ken@brightpathtutoring.example', owner: 'R05' },
  { lead_id: 'L-0004', company: 'Oakhaven Realty Inc.', contact_name: 'Maya Brooks', email: 'maya@oakhavenrealty.example', owner: 'R02' },
  { lead_id: 'L-0005', company: 'Copperleaf Yoga', contact_name: 'Ines Duarte', email: 'ines@copperleafyoga.example', owner: 'R04' },
  { lead_id: 'L-0006', company: 'Harbor Auto Garage', contact_name: 'Leo Tanaka', email: 'leo@harborauto.example', owner: 'R05' },
  { lead_id: 'L-0007', company: 'Mistral Design Studio', contact_name: 'Clara Weiss', email: 'clara@mistraldesign.example', owner: 'R03' },
  { lead_id: 'L-0008', company: 'Pinecrest Dental', contact_name: 'Owen Price', email: 'owen.price@gmail.com', owner: 'R02' },
];
const PUBLIC_DOMAINS = ['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'icloud.com', 'aol.com', 'proton.me'];
const LEGAL_SUFFIXES = ['llc', 'inc', 'co', 'ltd', 'corp', 'company', 'limited', 'gmbh', 'plc'];
const CUTOFF = 0.85;

const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.leads)) store.leads = SEED_LEADS;

const domainOf = (e) => (e && e.includes('@') ? e.split('@').pop().toLowerCase() : '');
const businessDomain = (e) => (PUBLIC_DOMAINS.includes(domainOf(e)) ? '' : domainOf(e));
const normCompany = (name) => {
  const words = (name || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean);
  while (words.length && LEGAL_SUFFIXES.includes(words[words.length - 1])) words.pop();
  return words.join('');
};
const surname = (name) => {
  const words = (name || '').toLowerCase().replace(/[^a-z ]/g, ' ').split(/\s+/).filter(Boolean);
  return words.length ? words[words.length - 1] : '';
};
// Levenshtein similarity, 0..1 (route.py uses difflib's ratio; same idea, same cutoff).
const similarity = (a, b) => {
  if (!a.length || !b.length) return 0;
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return 1 - prev[b.length] / Math.max(a.length, b.length);
};

let match = null;
const email = (lead.email || '').toLowerCase();
const byEmail = store.leads.find((l) => (l.email || '').toLowerCase() === email);
if (byEmail) {
  match = { kind: 'email', lead_id: byEmail.lead_id, owner: byEmail.owner };
} else {
  const company = normCompany(lead.company);
  const name = surname(lead.contact_name);
  const domain = businessDomain(lead.email);
  if (company) {
    const exact = store.leads.find((l) => normCompany(l.company) === company);
    if (exact) {
      match = { kind: 'company', lead_id: exact.lead_id, owner: exact.owner };
    } else {
      const fuzzy = store.leads
        .map((l) => ({ l, s: similarity(company, normCompany(l.company)) }))
        .filter((x) => x.s >= CUTOFF)
        .sort((x, y) => y.s - x.s)
        .find(({ l }) => (name && name === surname(l.contact_name)) || (domain && domain === businessDomain(l.email)));
      if (fuzzy) match = { kind: 'company', lead_id: fuzzy.l.lead_id, owner: fuzzy.l.owner };
    }
  }
}

if (match) {
  result.dedupe_hit = true;
  result.dedupe_match = `${match.kind}:${match.lead_id}`;
  result.flags.push(match.kind === 'email' ? 'duplicate_contact' : 'known_account');
} else {
  result.dedupe_hit = false;
  result.dedupe_match = '';
}
stamps.dedupe = now();
return [{ json: { lead, match, result, stamps, table_size: store.leads.length } }];

// Stage 3: enrich. *** STUB ***
// A real build calls an enrichment API here (Clearbit / Apollo style) with the email domain.
// This stand-in guesses industry from words in the domain and picks a company-size band from a
// hash of the domain. It is deterministic and free, but the size band is not real information.
// Values the form supplied are never overwritten. Public mail domains are skipped and flagged.
// The Code node sandbox has no performance timer, so stamps are Date.now() (1 ms resolution).
const now = () => Date.now();
const item = $input.first().json;
const { lead, result, stamps } = item;

const PUBLIC_DOMAINS = ['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'icloud.com', 'aol.com', 'proton.me'];
const INDUSTRY_KEYWORDS = {
  'Retail': ['boutique', 'market', 'supply', 'goods', 'outfitters', 'store', 'shop'],
  'Food & Beverage': ['bistro', 'bakery', 'coffee', 'catering', 'kitchen', 'cafe', 'deli'],
  'Professional Services': ['consulting', 'accounting', 'design', 'legal', 'advisors', 'law'],
  'Health & Wellness': ['clinic', 'dental', 'physio', 'pharmacy', 'wellness', 'chiro', 'health'],
  'Fitness': ['gym', 'athletics', 'yoga', 'fitness', 'pilates', 'crossfit'],
  'Beauty & Personal Care': ['salon', 'spa', 'barbers', 'beauty', 'nails'],
  'Real Estate': ['homes', 'realty', 'properties', 'estates'],
  'Education': ['learning', 'academy', 'tutoring', 'school'],
  'Automotive': ['auto', 'motors', 'tires', 'garage'],
  'Hospitality': ['inn', 'lodge', 'guesthouse', 'hotel', 'suites'],
};
const SIZE_BANDS = ['1-10', '11-50', '51-200'];
// FNV-1a: a tiny deterministic hash so the stub needs no crypto module.
const fnv1a = (s) => {
  let h = 0x811c9dc5;
  for (const ch of s) { h ^= ch.charCodeAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h;
};

const out = { ...lead };
const filled = {};
const domain = lead.email && lead.email.includes('@') ? lead.email.split('@').pop().toLowerCase() : '';
if (domain && PUBLIC_DOMAINS.includes(domain)) {
  result.flags.push('public_email_domain');
} else if (domain) {
  const stem = domain.split('.')[0];
  if (!out.industry) {
    let best = null; // longest keyword wins
    for (const [industry, words] of Object.entries(INDUSTRY_KEYWORDS)) {
      for (const w of words) if (stem.includes(w) && (!best || w.length > best[0])) best = [w.length, industry];
    }
    if (best) out.industry = filled.industry = best[1];
  }
  if (!out.company_size) out.company_size = filled.company_size = SIZE_BANDS[fnv1a(domain) % SIZE_BANDS.length];
  if (!out.industry) result.flags.push('enrich_no_industry');
}
result.enriched_fields = filled;
result.enrich_source = 'stub';
stamps.enrich = now();
return [{ json: { ...item, lead: out, result, stamps } }];

// Stage 4: score. Fit score 0-100, the same points as fit_score() in route.py:
// buying intent (source) + company size + industry fit + business email.
// The Code node sandbox has no performance timer, so stamps are Date.now() (1 ms resolution).
const now = () => Date.now();
const item = $input.first().json;
const { lead, result, stamps } = item;

const SOURCE_POINTS = { demo_request: 35, free_trial: 30, website_form: 20, content_download: 10 };
const SIZE_POINTS = { '51-200': 30, '11-50': 25, '1-10': 10 };
const CORE_INDUSTRIES = ['Health & Wellness', 'Fitness', 'Beauty & Personal Care', 'Professional Services'];
const PUBLIC_DOMAINS = ['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'icloud.com', 'aol.com', 'proton.me'];

let score = SOURCE_POINTS[lead.source] || 0;
score += SIZE_POINTS[lead.company_size] || 0;
score += CORE_INDUSTRIES.includes(lead.industry) ? 20 : lead.industry ? 10 : 0;
const domain = lead.email && lead.email.includes('@') ? lead.email.split('@').pop().toLowerCase() : '';
score += domain && !PUBLIC_DOMAINS.includes(domain) ? 15 : 0;

result.score = Math.min(score, 100);
stamps.score = now();
return [{ json: { ...item, result, stamps } }];

// Stage 5: assign.
// A dedupe hit goes to the rep who already owns that person or account. Otherwise: round-robin
// within the lead's region, skipping reps whose open leads are at capacity. If the whole region
// is full, the least-loaded rep in the region gets it and the lead is flagged over_capacity, so it
// is never left unowned. Unknown region: the same rule across all reps, flagged unknown_region.
// Rep loads and the rotation position live in workflow static data, next to the leads table.
// The Code node sandbox has no performance timer, so stamps are Date.now() (1 ms resolution).
const now = () => Date.now();
const item = $input.first().json;
const { lead, match, result, stamps } = item;
const capacity = Number($('Settings').first().json.rep_capacity);

const REPS = [
  { rep_id: 'R01', rep_name: 'Danielle Johnson', region: 'North America' },
  { rep_id: 'R02', rep_name: 'Joshua Walker', region: 'North America' },
  { rep_id: 'R03', rep_name: 'Jill Rhodes', region: 'EMEA' },
  { rep_id: 'R04', rep_name: 'Patricia Miller', region: 'EMEA' },
  { rep_id: 'R05', rep_name: 'Robert Johnson', region: 'APAC' },
  { rep_id: 'R06', rep_name: 'Jeffery Wagner', region: 'LATAM' },
];
// Open leads (status new or contacted) each rep already holds when the demo starts.
const SEED_LOAD = { R01: 12, R02: 7, R03: 9, R04: 8, R05: 10, R06: 4 };

const store = $getWorkflowStaticData('global');
if (!store.load) store.load = { ...SEED_LOAD };
if (!store.next) store.next = {};
const take = (repId) => { store.load[repId] = (store.load[repId] || 0) + 1; return repId; };

let repId, reason;
if (match && REPS.some((r) => r.rep_id === match.owner)) {
  repId = take(match.owner);
  reason = `existing owner (${match.kind} match)`;
} else {
  let poolKey = lead.region;
  let pool = REPS.filter((r) => r.region === lead.region).map((r) => r.rep_id).sort();
  if (!pool.length) {
    result.flags.push('unknown_region');
    poolKey = '*';
    pool = REPS.map((r) => r.rep_id).sort();
  }
  const start = store.next[poolKey] || 0;
  for (let step = 0; step < pool.length && !repId; step++) {
    const i = (start + step) % pool.length;
    if ((store.load[pool[i]] || 0) < capacity) {
      store.next[poolKey] = (i + 1) % pool.length;
      repId = take(pool[i]);
      reason = 'round_robin' + (step ? ` (skipped ${step} at capacity)` : '');
    }
  }
  if (!repId) {
    const least = [...pool].sort((a, b) => (store.load[a] - store.load[b]) || a.localeCompare(b))[0];
    repId = take(least);
    reason = 'least_loaded (region at capacity)';
    result.flags.push('over_capacity');
  }
}

// Add the lead to the leads table so the next submission dedupes against it.
store.leads.push({
  lead_id: lead.lead_id || `N8N-${String(store.leads.length + 1).padStart(4, '0')}`,
  company: lead.company || '', contact_name: lead.contact_name || '', email: lead.email || '', owner: repId,
});

const rep = REPS.find((r) => r.rep_id === repId);
result.assigned_rep = repId;
result.rep_name = rep.rep_name;
result.assign_reason = reason;
result.rep_open_leads = store.load[repId];
stamps.assign = now();
return [{ json: { ...item, result, stamps } }];

// Stage 6a: compose the alert text (same wording as build_alert() in route.py).
const item = $input.first().json;
const { lead, result } = item;
const who = result.rep_name ? `${result.rep_name} (${result.assigned_rep})` : result.assigned_rep || 'nobody';
const lines = [
  `:rotating_light: New inbound lead for ${who}`,
  `*${lead.contact_name || '?'}* at *${lead.company || '?'}* (${lead.region || 'region unknown'})`,
  `Email: ${lead.email} | Source: ${lead.source} | Fit score: ${result.score}`,
  `Industry: ${lead.industry || '?'} | Size: ${lead.company_size || '?'}`,
  `Why this rep: ${result.assign_reason}`,
];
if (result.dedupe_hit) lines.push(`Known contact/account: ${result.dedupe_match}`);
if (result.flags.length) lines.push(`Flags: ${result.flags.join(', ')}`);
lines.push('Reply now: inbound leads answered within the hour close far more often.');
const text = lines.join('\n');
const logLine = `[${new Date().toISOString()}] ${result.lead_id || '(new lead)'} -> ${result.assigned_rep}\n${text}\n---\n`;
return [{ json: { ...item, alert_text: text, alert_log_line: logLine } }];

// Turn the timing stamps into ms per stage and build the JSON response.
// Each stage's time runs from the end of the previous stage to the end of this one, so it
// includes n8n's own hand-off between nodes, not just the JavaScript inside the node.
// The Code node sandbox has no performance timer, so stamps are Date.now() (1 ms resolution).
const now = () => Date.now();
const end = now();
const base = $('Compose alert').first().json;
const { result, stamps } = base;
const channel = $('Settings').first().json.slack_alerts ? 'slack' : 'log';
const round = (x) => Math.round(x * 100) / 100;
const order = ['validate', 'dedupe', 'enrich', 'score', 'assign'];
const stage_ms = {};
let prev = stamps.start;
for (const s of order) { stage_ms[s] = round(stamps[s] - prev); prev = stamps[s]; }
stage_ms.alert = round(end - stamps.assign);
return [{
  json: {
    ...result,
    alert_channel: channel,
    flags: [...result.flags, channel === 'slack' ? 'alert_slack' : 'alert_logged'],
    stage_ms,
    total_ms: round(end - stamps.start),
  },
}];

// Demo only: clear the leads table, rep loads and rotation so a replay starts from the seed.
// Remove this branch (or put auth on it) before using the workflow for real.
const store = $getWorkflowStaticData('global');
for (const k of Object.keys(store)) delete store[k];
return [{ json: { reset: true } }];
